// INHERITANCE + POLYMORPHISM: overdraft behavior
package com.bank.oop.model;

import java.math.BigDecimal;

public class CurrentAccount extends Account {

    private final BigDecimal overdraftLimit;

    public CurrentAccount(String accountId, String holderName, BigDecimal balance,
                          BigDecimal overdraftLimit) {
        super(accountId, holderName, balance, "CURRENT");
        this.overdraftLimit = overdraftLimit;
    }

    // ═══ POLYMORPHISM: override withdraw to allow overdraft ═══
    @Override
    public void withdraw(BigDecimal amount) {
        BigDecimal effectiveBalance = getBalance().add(overdraftLimit);
        if (effectiveBalance.compareTo(amount) < 0) {
            throw new com.bank.oop.exception.InsufficientFundsException(
                "Current account effective limit Rs." + effectiveBalance
                + " (balance Rs." + getBalance() + " + overdraft Rs." + overdraftLimit
                + ") insufficient for Rs." + amount);
        }
        setBalance(getBalance().subtract(amount));  // can go negative up to overdraft
    }

    // Current accounts earn ZERO interest — use parent's default
    // calculateInterest() returns BigDecimal.ZERO (inherited from Account)

    @Override
    public String getTypeDescription() {
        return "Current Account (overdraft limit Rs." + overdraftLimit + ")";
    }

    public BigDecimal getOverdraftLimit() { return overdraftLimit; }
}
