// POLYMORPHISM IN ACTION — processes ALL account types with ONE loop
package com.bank.oop.service;

import com.bank.oop.dto.AccountSummary;
import com.bank.oop.model.*;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
@Slf4j
public class InterestBatchService {

    // Simulated accounts — in production, loaded from DB
    private final List<Account> allAccounts = List.of(
        new SavingsAccount("SAV2001", "Rajesh Kumar", new BigDecimal("125000.50"), new BigDecimal("0.04")),
        new CurrentAccount("CUR3001", "Priya Sharma", new BigDecimal("850000"), new BigDecimal("100000")),
        new NRIAccount("NRI5001", "Amit Patel", new BigDecimal("2500000"), "USD", new BigDecimal("83.50"), new BigDecimal("0.035")),
        new SavingsAccount("SAV2002", "Deepa Reddy", new BigDecimal("45000"), new BigDecimal("0.04"))
    );

    // ═══ POLYMORPHISM: ONE method handles ALL account types! ═══
    public List<AccountSummary> processMonthEndInterest() {
        List<AccountSummary> results = new ArrayList<>();

        for (Account account : allAccounts) {
            // POLYMORPHIC CALL: each account type calculates its own interest!
            BigDecimal interest = account.calculateInterest();
            // SavingsAccount → balance × 4% / 12
            // CurrentAccount → 0 (no interest)
            // NRIAccount → balance × 3.5% / 12
            // We DON'T need to check account type! Polymorphism handles it.

            if (interest.signum() > 0) {
                account.deposit(interest);
                log.info("Interest credited: {} → Rs.{}", account.getAccountId(), interest);
            }

            results.add(new AccountSummary(
                account.getAccountId(),
                account.getHolderName(),
                account.getAccountType(),
                account.getBalance(),
                interest,
                account.getTypeDescription()  // POLYMORPHIC: each type returns its own description
            ));
        }

        log.info("Month-end processed: {} accounts", results.size());
        return results;
    }

    // ═══ POLYMORPHISM: withdrawal — each type has different rules ═══
    public String processWithdrawal(String accountId, BigDecimal amount) {
        Account account = allAccounts.stream()
            .filter(a -> a.getAccountId().equals(accountId))
            .findFirst()
            .orElseThrow(() -> new IllegalArgumentException("Account not found: " + accountId));

        account.withdraw(amount);
        // SavingsAccount → checks minimum balance (Rs.1000)
        // CurrentAccount → allows overdraft (balance + overdraft limit)
        // NRIAccount → logs foreign currency equivalent + FEMA check

        return "Withdrawal Rs." + amount + " from " + account;
    }

    public List<Account> getAllAccounts() { return allAccounts; }
}
